head.b:skin:
/* SUSHI ELITE v87.0 - GOLDEN MASTER */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --radius-xl: 20px;
    --z-marquee: 1040; --z-navbar: 1030; --z-floating: 1035;
}

[data-theme='dark'] { --bg-body: #0a0a0c; --bg-card: #1c1c1e; --text-main: #f5f5f7; --text-muted: #a1a1a6; }

body { font-family: "Inter", sans-serif; background: var(--bg-body); color: var(--text-main); padding-top: 145px; padding-bottom: 90px; overflow-x: hidden; }

/* UTILS */
.header { background: var(--bg-card); height: 80px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); top: 30px; transition: 0.3s; }
.breadcrumb-bar { position: fixed; top: 110px; left: 0; width: 100%; height: 35px; background: var(--bg-body); z-index: 1025; display: flex; align-items: center; padding: 0 15px; border-bottom: 1px solid rgba(0,0,0,0.05); font-size: 0.8rem; overflow-x: auto; white-space: nowrap; }

/* CARD STYLES */
.product-card { background: var(--bg-card); border-radius: var(--radius-xl); overflow: hidden; height: 100%; transition: 0.3s; position: relative; border: 1px solid rgba(0,0,0,0.05); }
.product-card:hover { transform: translateY(-5px); box-shadow: 0 10px 30px rgba(0,0,0,0.1); }
.product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #f0f0f0; cursor: pointer; }
.product-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.product-card:hover .product-img { transform: scale(1.05); }

/* ACTIONS & BADGES */
.wish-btn-card { position: absolute; bottom: 10px; right: 10px; z-index: 10; width: 35px; height: 35px; background: rgba(255,255,255,0.9); border-radius: 50%; border: none; display: flex; align-items: center; justify-content: center; color: #ccc; transition: 0.2s; box-shadow: 0 2px 8px rgba(0,0,0,0.1); cursor: pointer; }
.wish-btn-card.active { color: var(--primary); transform: scale(1.1); }
.desktop-actions { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%) translateY(20px); opacity: 0; transition: 0.3s; z-index: 20; width: 90%; text-align: center; }
.product-card:hover .desktop-actions { opacity: 1; transform: translateX(-50%) translateY(0); }
@media (max-width: 991px) { .desktop-actions { display: none; } }

.badge-float { position: absolute; z-index: 10; padding: 4px 10px; border-radius: 4px; font-weight: 800; font-size: 0.65rem; color: #fff; box-shadow: 0 4px 10px rgba(0,0,0,0.2); }
.badge-hot { top: 10px; left: 10px; background: linear-gradient(45deg, #ff0000, #ff8800); }
.badge-stock { top: 10px; left: 10px; background: rgba(0,0,0,0.7); backdrop-filter: none; } 
.badge-low { background: #e67e22; top: 10px; left: 10px; animation: pulse 2s infinite; }
.badge-out { background: #c0392b; top: 10px; left: 10px; }
.badge-sale { top: 38px; left: 10px; background: #000; } 
@keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.6; } 100% { opacity: 1; } }

/* CART & UI */
.floating-cart { position: fixed; bottom: 85px; left: 15px; right: 15px; background: rgba(29, 29, 31, 0.85); backdrop-filter: blur(10px); color: #fff; padding: 12px 20px; border-radius: 50px; z-index: var(--z-floating); display: flex; justify-content: space-between; align-items: center; box-shadow: 0 10px 30px rgba(0,0,0,0.25); transform: translateY(150%); transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.floating-cart.active { transform: translateY(0); }
.floating-cart .price-tag { background: rgba(255,255,255,0.2); padding: 4px 12px; border-radius: 20px; font-weight: 700; margin-left: 10px; }

.delivery-progress { height: 8px; background: #eee; border-radius: 10px; overflow: hidden; margin-top: 5px; }
.delivery-bar { height: 100%; background: var(--primary); width: 0%; transition: width 0.5s; }

.filter-scroll { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 5px; scrollbar-width: none; }
.filter-scroll::-webkit-scrollbar { display: none; }
.filter-chip { white-space: nowrap; padding: 8px 18px; border-radius: 50px; background: var(--bg-card); border: 1px solid rgba(0,0,0,0.1); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.3s; font-size: 0.85rem; }
.filter-chip:hover, .filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }

.module-section { display: none !important; opacity: 0; animation: fadeIn 0.4s forwards; }
.module-section.active { display: block !important; opacity: 1; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.marquee-bar { position: fixed; top: 0; left: 0; width: 100%; height: 30px; background: #000; color: #fff; z-index: var(--z-marquee); overflow: hidden; display: flex; align-items: center; font-size: 0.75rem; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; }
.marquee-content { display: inline-block; white-space: nowrap; animation: marquee 20s linear infinite; padding-left: 100%; }
@keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }

#store-closed-banner { top: 30px; z-index: 1050; font-size: 0.75rem; padding: 5px 0; background: rgba(220, 53, 69, 0.9); backdrop-filter: blur(4px); }

.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 1060; width: 90%; max-width: 350px; pointer-events: none; }
.toast { pointer-events: auto; background: var(--bg-card); color: var(--text-main); border: 1px solid rgba(0,0,0,0.1); box-shadow: 0 10px 30px rgba(0,0,0,0.1); border-radius: 12px; margin-bottom: 10px; }

.stock-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; margin-right: 5px; }
.bg-stock-ok { background-color: #198754; }
.variant-select { font-size: 0.85rem; padding: 2px 8px; border-radius: 4px; border: 1px solid #ddd; background: var(--bg-body); color: var(--text-main); cursor: pointer; }

body.script:
//
const API_URL = "https://script.google.com/macros/s/AKfycbxnDZiQY_tpQexinqIgq2H1xXEDvwrDpmnItcLh5uFGB1VqB12uh6M4-P6jGhSQmXwe/exec"; 

const App = {
    Config: { baseCurrency: 'MAD', freeShipThreshold: 200, waNumber: '212600000000', deliveryZones: {} },
    Symbols: { 'MAD': ' DH', 'EUR': ' €', 'USD': '$ ' },
    State: { catalog:[], cart:[], wishlist:[], recent:[], history:[], user:null, activeCat:'All', searchTerm:'', currency:'MAD', lastActive:0, lastCurrencyChange:0, batchSize: 12, visibleCount: 0, activeCoupon: null },

    Utils: {
        getPriceObj: (i) => {
            const c = App.State.currency;
            if(c==='EUR') return {now: i.price_EUR, old: i.oldPrice_EUR};
            if(c==='USD') return {now: i.price_USD, old: i.oldPrice_USD};
            return {now: i.price_MAD, old: i.oldPrice_MAD};
        },
        fmt: (n) => App.State.currency==='USD' ? '$ '+n.toFixed(2) : n.toFixed(2)+App.Symbols[App.State.currency],
        save: (k) => localStorage.setItem(k, JSON.stringify(App.State[k.split('_')[1]])),
        load: (k) => { try { return JSON.parse(localStorage.getItem(k))||[] } catch(e){return[]} },
        checkStock: (item) => {
            if(!item || item.stock === 0) return { disabled: true, badge: '<div class="badge-float badge-out">SOLD OUT</div>' };
            if(item.stock < 5) return { disabled: false, badge: '<div class="badge-float badge-low">LOW STOCK</div>' };
            if(item.hot) return { disabled: false, badge: '<div class="badge-float badge-hot">HOT</div>' };
            return { disabled: false, badge: '' };
        }
    },

    // SEO Injection
    SEO: {
        generateSchema: () => {
            const schema = {
                "@context": "https://schema.org",
                "@type": "Restaurant",
                "name": "Sushi Elite",
                "image": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png",
                "menu": {
                    "@type": "Menu",
                    "hasMenuSection": App.State.catalog.map(i => ({
                        "@type": "MenuSection",
                        "name": i.title,
                        "offers": { "@type": "Offer", "price": i.price_MAD, "priceCurrency": "MAD" }
                    }))
                }
            };
            document.getElementById('json-ld-store').textContent = JSON.stringify(schema);
        }
    },

    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),
        login: () => {
            const p = document.getElementById('login-phone').value, pass = document.getElementById('login-pass').value;
            if(!p) return alert('Enter Phone');
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'login', data:{phone:p, password:pass}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.State.user = {id:res.userId, name:res.name, phone:p};
                    localStorage.setItem('se_user', JSON.stringify(App.State.user));
                    location.reload();
                } else alert(res.message);
            });
        },
        register: () => {
            const n = document.getElementById('reg-name').value, p = document.getElementById('reg-phone').value, pass = document.getElementById('reg-pass').value;
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'register', data:{name:n, phone:p, password:pass}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.State.user = {id:res.userId, name:n, phone:p};
                    localStorage.setItem('se_user', JSON.stringify(App.State.user));
                    location.reload();
                } else alert(res.message);
            });
        },
        logout: () => { localStorage.removeItem('se_user'); location.reload(); },
        check: () => {
            const u = App.State.user;
            if(u) {
                if(document.getElementById('profile-logged-in')) document.getElementById('profile-logged-in').classList.remove('d-none');
                if(document.getElementById('profile-logged-out')) document.getElementById('profile-logged-out').classList.add('d-none');
                if(document.getElementById('order-history-section')) document.getElementById('order-history-section').classList.remove('d-none');
                if(document.getElementById('user-name-display')) document.getElementById('user-name-display').innerText = u.name;
                if(document.getElementById('auth-btn')) document.getElementById('auth-btn').innerHTML = '<i class="bi bi-person-check-fill text-success"></i>';
            }
        }
    },

    API: {
        init: () => {
            // Check Store Status & Config
            fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res=>{
                if(!res.isOpen) {
                    const b = document.getElementById('store-closed-banner');
                    b.innerText = "⛔ STORE CLOSED (" + res.hours + ") - CHECKOUT DISABLED";
                    b.classList.remove('d-none');
                    document.getElementById('checkout-btn').disabled = true;
                }
                if(res.config) {
                    App.Config.freeShipThreshold = res.config.Free_Shipping_Threshold || 200;
                    const zones = {};
                    const select = document.getElementById('checkout-zone');
                    select.innerHTML = '';
                    for(const key in res.config) {
                        if(key.startsWith('Delivery_')) {
                            const city = key.replace('Delivery_','');
                            zones[city] = res.config[key];
                            const opt = document.createElement('option');
                            opt.value = city;
                            opt.innerText = city + " (+" + res.config[key] + " DH)";
                            select.appendChild(opt);
                        }
                    }
                    const pick = document.createElement('option'); pick.value='Pickup'; pick.innerText='Pickup (0 DH)';
                    select.prepend(pick);
                    App.Config.deliveryZones = zones;
                }
            });

            fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.State.catalog = res.data.map(i=>({
                        id: i.id, title: i.title, cat: i.category,
                        price_MAD: parseFloat(i.price_MAD), price_EUR: parseFloat(i.price_EUR), price_USD: parseFloat(i.price_USD),
                        oldPrice_MAD: parseFloat(i.oldPrice_MAD), oldPrice_EUR: parseFloat(i.oldPrice_EUR), oldPrice_USD: parseFloat(i.oldPrice_USD),
                        stock: i.stock, img: i.image, hot: (i.tags||'').includes('hot')
                    }));
                    App.Catalog.renderFilters();
                    App.Catalog.renderBatch(true);
                    App.Recent.render();
                    App.SEO.generateSchema();
                    if(App.State.user) App.API.syncDown(App.State.user.id);
                }
            });
        },
        syncDown: (uid) => {
            fetch(API_URL + '?action=getUserData&userId='+uid).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    if(res.cart) { App.State.cart = JSON.parse(res.cart); App.Cart.render(); }
                    if(res.wishlist) {
                        const rawIds = String(res.wishlist).split(',').map(s=>s.trim().replace('p-','')).filter(s=>s!=='');
                        App.State.wishlist = App.State.catalog.filter(p=> rawIds.includes(String(p.id).replace('p-','')));
                        if(document.getElementById('nav-wish-count')) document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
                        App.Catalog.renderBatch(true);
                    }
                    if(res.joinDate && document.getElementById('user-join-date')) document.getElementById('user-join-date').innerText = new Date(res.joinDate).toLocaleDateString();
                    if(res.currency && (Date.now() - App.State.lastCurrencyChange > 15000)) {
                        App.State.currency = res.currency;
                        if(document.getElementById('curr-btn')) document.getElementById('curr-btn').innerText = res.currency;
                        App.Cart.render();
                    }
                    if(res.orders) {
                        App.State.history = res.orders;
                        App.Profile.renderOrders();
                    }
                }
            });
        },
        push: (type) => {
            if(!App.State.user) return;
            const pl = type==='cart' ? {userId:App.State.user.id, cartJson:JSON.stringify(App.State.cart), currency:App.State.currency} 
                                     : {userId:App.State.user.id, items:App.State.wishlist.map(i=>i.id).join(',')};
            fetch(API_URL, {method:'POST', body:JSON.stringify({action: type==='cart'?'syncCart':'syncWishlist', data:pl})});
        }
    },

    Catalog: {
        renderFilters: () => {
            const c = document.getElementById('category-filters'); if(!c) return;
            const cats = ['All', ...new Set(App.State.catalog.map(i=>i.cat))];
            c.innerHTML = cats.map(k => `<button class="filter-chip ${k==='All'?'active':''}" onclick="App.Catalog.filter('${k}', this)">${k}</button>`).join('');
        },
        search: (term) => {
            App.State.searchTerm = term.toLowerCase();
            App.Catalog.renderBatch(true);
        },
        filter: (cat, btn) => {
            App.State.activeCat = cat; 
            App.State.visibleCount = 0; 
            document.getElementById('product-grid-root').innerHTML = '';
            if(btn) { document.querySelectorAll('.filter-chip').forEach(e=>e.classList.remove('active')); btn.classList.add('active'); }
            App.Catalog.renderBatch();
        },
        renderBatch: (reset) => {
            const c = document.getElementById('product-grid-root');
            if(reset) { c.innerHTML=''; App.State.visibleCount=0; }

            let filtered = App.State.catalog;
            if(App.State.activeCat !== 'All') filtered = filtered.filter(i=>i.cat===App.State.activeCat);
            if(App.State.searchTerm) filtered = filtered.filter(i=>i.title.toLowerCase().includes(App.State.searchTerm));

            const batch = filtered.slice(App.State.visibleCount, App.State.visibleCount+App.State.batchSize);
            batch.forEach(i => c.innerHTML += App.Catalog.createCard(i));
            App.State.visibleCount += App.State.batchSize;

            const sentinel = document.getElementById('scroll-sentinel');
            if(sentinel) {
                sentinel.style.display = (App.State.visibleCount >= filtered.length) ? 'none' : 'flex';
                new IntersectionObserver(e=>{ if(e[0].isIntersecting) App.Catalog.renderBatch(); }).observe(sentinel);
            }
        },
        createCard: (i) => {
            const p = App.Utils.getPriceObj(i);
            const stockInfo = App.Utils.checkStock(i);
            const isWish = App.State.wishlist.some(w=>w.id===i.id) ? 'active' : '';

            let badges = stockInfo.badge;
            if(p.old > 0) badges += `<div class="badge-float badge-sale">SALE</div>`;

            const priceDisplay = p.old > 0 ? 
                `<span class="text-decoration-line-through text-muted small me-2">${App.Utils.fmt(p.old)}</span><span class="text-danger fw-bold">${App.Utils.fmt(p.now)}</span>` : 
                `<span class="text-primary fw-bold">${App.Utils.fmt(p.now)}</span>`;

            return `<div class="col-6 col-md-4"><div class="product-card h-100">
                ${badges}
                <div class="product-img-wrapper">
                    <button class="wish-btn-card ${isWish}" onclick="App.Wishlist.toggle('${i.id}', this);event.stopPropagation()"><i class="bi bi-heart${isWish?'-fill text-danger':''}"></i></button>
                    <img src="${i.img}" class="product-img" onclick="App.QuickView.open('${i.id}')">
                    <div class="desktop-actions">
                        <button class="btn btn-light rounded-pill shadow-sm fw-bold px-4" onclick="App.QuickView.open('${i.id}')">
                            <i class="bi bi-eye"></i> Quick View
                        </button>
                    </div>
                </div>
                <div class="p-3">
                    <h6 class="product-title">${i.title}</h6>
                    <div class="d-flex justify-content-between align-items-center">
                        <div>${priceDisplay}</div>
                        <button class="btn btn-sm btn-dark rounded-circle" onclick="App.Cart.add('${i.id}', this)" ${stockInfo.disabled ? 'disabled' : ''}><i class="bi bi-plus"></i></button>
                    </div>
                </div>
            </div></div>`;
        }
    },

    Cart: {
        add: (id, btn) => {
            App.State.lastActive = Date.now();
            const item = App.State.catalog.find(i=>i.id===id); if(!item) return;
            const ex = App.State.cart.find(c=>c.id===id && c.variant.name==='Regular');
            if(ex) ex.qty++; else App.State.cart.push({...item, qty:1, variant:{name:'Regular', mult:1.0}});
            App.Utils.save('se_cart');
            App.Cart.render(); App.Cart.updateBadge(); App.API.push('cart');
            if(btn) alert('Added to Cart'); 
        },
        remove: (idx) => { 
            App.State.lastActive = Date.now();
            App.State.cart.splice(idx,1); App.Utils.save('se_cart'); App.Cart.render(); App.Cart.updateBadge(); App.API.push('cart');
        },
        updateQty: (idx, d) => { 
            App.State.lastActive = Date.now();
            const i = App.State.cart[idx]; if(i.qty+d > 0) { i.qty+=d; App.Utils.save('se_cart'); App.Cart.render(); App.Cart.updateBadge(); App.API.push('cart'); } 
        },
        changeVariant: (idx, el) => {
            const val = el.value.split('|');
            App.State.cart[idx].variant = { name: val[0], mult: parseFloat(val[1]) };
            App.Utils.save('se_cart'); App.Cart.render();
        },
        duplicate: (idx) => {
            const item = {...App.State.cart[idx]};
            App.State.cart.splice(idx + 1, 0, item);
            App.Utils.save('se_cart'); App.Cart.render(); App.Cart.updateBadge();
        },
        checkClear: () => { if(confirm('Empty entire cart?')) App.Cart.clear(); },
        clear: () => { App.State.lastActive = Date.now(); App.State.cart=[]; App.Utils.save('se_cart'); App.Cart.render(); App.Cart.updateBadge(); App.API.push('cart'); },

        updateBadge: () => { 
            const el = document.getElementById('nav-cart-count'); 
            if(el) el.innerText = App.State.cart.reduce((a,b)=>a+b.qty,0); 
        },

        render: () => {
            const list = document.getElementById('cart-items-list');
            const empty = document.getElementById('cart-empty-view');
            const content = document.getElementById('cart-content-row');
            const float = document.getElementById('floating-cart');
            const tracker = document.getElementById('delivery-tracker');
            const bar = document.getElementById('delivery-bar');
            const msg = document.getElementById('delivery-msg');
            const amt = document.getElementById('delivery-amount');

            if(window.location.hash==='#cart') float?.classList.remove('active');
            else if(App.State.cart.length>0) float?.classList.add('active'); else float?.classList.remove('active');

            if(!list) return;

            if(App.State.cart.length===0) { 
                if(empty) empty.classList.remove('d-none'); 
                if(content) content.classList.add('d-none'); 
                return; 
            }
            if(empty) empty.classList.add('d-none'); 
            if(content) content.classList.remove('d-none');

            let total = 0;
            list.innerHTML = App.State.cart.map((i, idx) => {
                const priceVal = App.Utils.getPriceObj(i).now; 
                const row = priceVal * i.variant.mult * i.qty; 
                total += row;
                return `<div class="d-flex gap-3 mb-3 border-bottom pb-3">
                    <img src="${i.img}" width="60" class="rounded object-fit-cover">
                    <div class="flex-grow-1">
                        <div class="d-flex justify-content-between">
                            <h6 class="mb-0">${i.title}</h6>
                            <b class="text-primary">${App.Utils.fmt(row)}</b>
                        </div>
                        <div class="d-flex justify-content-between align-items-end mt-2">
                            <select class="variant-select form-select form-select-sm w-auto py-0" onchange="App.Cart.changeVariant(${idx}, this)">
                                <option value="Regular|1.0" ${i.variant.name==='Regular'?'selected':''}>Regular</option>
                                <option value="Box|1.2" ${i.variant.name==='Box'?'selected':''}>Box (1.2x)</option>
                                <option value="Party|1.5" ${i.variant.name==='Party'?'selected':''}>Party (1.5x)</option>
                            </select>
                            <div class="d-flex align-items-center gap-2">
                                <button class="btn btn-sm btn-outline-secondary py-0 px-2" onclick="App.Cart.updateQty(${idx},-1)">-</button>
                                <b class="small">${i.qty}</b>
                                <button class="btn btn-sm btn-outline-secondary py-0 px-2" onclick="App.Cart.updateQty(${idx},1)">+</button>
                                <button class="btn btn-sm text-muted border-0" onclick="App.Cart.duplicate(${idx})"><i class="bi bi-files"></i></button>
                                <button class="btn btn-sm text-danger border-0" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                            </div>
                        </div>
                    </div>
                </div>`;
            }).join('');

            // RESTORED: Free Shipping Meter
            if(tracker) {
                tracker.classList.remove('d-none');
                if(total >= App.Config.freeShipThreshold) {
                    msg.innerText = "You've unlocked FREE Delivery!";
                    amt.innerText = "";
                    bar.style.width = "100%";
                    bar.classList.add("bg-success");
                } else {
                    const left = App.Config.freeShipThreshold - total;
                    msg.innerText = "Add more for FREE Delivery!";
                    amt.innerText = "Add " + App.Utils.fmt(left);
                    const pct = (total / App.Config.freeShipThreshold) * 100;
                    bar.style.width = pct + "%";
                    bar.classList.remove("bg-success");
                }
            }

            // Delivery Calculation
            const zone = document.getElementById('checkout-zone').value;
            let deliveryCost = App.Config.deliveryZones[zone] || 0;
            if(total >= App.Config.freeShipThreshold) deliveryCost = 0;

            // Coupon Calculation
            let discountAmt = 0;
            if(App.State.activeCoupon) discountAmt = total * App.State.activeCoupon.discount;

            const finalTotal = total + deliveryCost - discountAmt;
            App.State.currentTotal = finalTotal;

            document.getElementById('sum-sub').innerText = App.Utils.fmt(total);
            document.getElementById('sum-del').innerText = App.Utils.fmt(deliveryCost);
            document.getElementById('sum-disc').innerText = '-' + App.Utils.fmt(discountAmt);
            if(discountAmt > 0) document.getElementById('row-disc').classList.remove('d-none');

            document.getElementById('sum-total').innerText = App.Utils.fmt(finalTotal);
            document.getElementById('float-total').innerText = App.Utils.fmt(finalTotal);
            document.getElementById('float-count').innerText = App.State.cart.reduce((a,b)=>a+b.qty,0);
        },

        applyCoupon: () => {
            const code = document.getElementById('coupon-code').value.toUpperCase();
            const feedback = document.getElementById('coupon-feedback');

            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'checkCoupon', data:{code:code}})})
            .then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.State.activeCoupon = res;
                    feedback.innerText = 'Applied! ' + (res.discount*100) + '% Off';
                    feedback.className = 'small mb-3 text-success fw-bold';
                    App.Cart.render();
                } else {
                    feedback.innerText = 'Invalid Code';
                    feedback.className = 'small mb-3 text-danger';
                }
            });
        },

        checkout: () => {
            const name = document.getElementById('checkout-name').value;
            const phone = document.getElementById('checkout-phone').value;
            const address = document.getElementById('checkout-address').value;
            const zone = document.getElementById('checkout-zone').value;

            if(!name || !phone) return alert('Name & Phone Required');
            if(zone !== 'Pickup' && !address) return alert('Address Required');

            const btn = document.getElementById('checkout-btn');
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Processing...';
            btn.disabled = true;

            // Send cart as STRUCTURED object for backend validation
            const orderData = {
                userId: App.State.user ? App.State.user.id : null,
                name: name,
                phone: phone,
                address: address,
                zone: zone,
                cart: JSON.stringify(App.State.cart.map(i => ({
                    id: i.id, 
                    qty: i.qty, 
                    variantMult: i.variant.mult, 
                    title: i.title + " (" + i.variant.name + ")"
                }))),
                couponCode: App.State.activeCoupon ? App.State.activeCoupon.code : null,
                method: 'Cash'
            };

            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'placeOrder', data: orderData }) })
            .then(r => r.json())
            .then(res => {
                if(res.status === 'success') {
                    const orderId = res.orderId;
                    let msg = `*NEW ORDER ${orderId}* %0A`;
                    msg += `👤 ${name} (${phone}) %0A`;
                    msg += `🚚 ${zone} - ${address} %0A`;
                    msg += `--------------------%0A`;
                    App.State.cart.forEach(i => msg += `🍱 ${i.qty}x ${i.title} [${i.variant.name}] %0A`);
                    msg += `--------------------%0A`;
                    msg += `💰 *TOTAL: ${App.Utils.fmt(res.secureTotal)}*`; // Use SERVER total

                    App.State.history.unshift({
                        id: orderId, 
                        date: new Date().toLocaleDateString(), 
                        total: res.secureTotal, 
                        items: App.State.cart.length, 
                        status: 'Sent'
                    });

                    // 🔥 EMPTY CART LOGIC
                    App.State.cart = [];
                    App.Utils.save('se_cart');
                    App.Cart.render();
                    App.API.push('cart'); 

                    window.open(`https://wa.me/${App.Config.waNumber}?text=${msg}`, '_blank');
                    window.location.reload();
                } else {
                    alert('Order Failed: ' + res.message);
                    btn.disabled = false;
                    btn.innerHTML = 'CHECKOUT';
                }
            })
            .catch(err => {
                alert('Network Error');
                btn.disabled = false;
                btn.innerHTML = 'CHECKOUT';
            });
        }
    },

    Recent: {
        add: (id) => {
            App.State.recent = App.State.recent.filter(x => x !== id);
            App.State.recent.unshift(id);
            App.State.recent = App.State.recent.slice(0, 6);
            App.Utils.save('se_recent');
            App.Recent.render();
        },
        render: () => {
            const c = document.getElementById('recent-grid');
            const cont = document.getElementById('recent-container');
            if(!c || !cont) return;

            if(App.State.recent.length === 0) {
                cont.classList.add('d-none');
                return;
            }
            cont.classList.remove('d-none');
            const items = App.State.catalog.filter(p => App.State.recent.includes(p.id));
            c.innerHTML = items.map(i => App.Catalog.createCard(i)).join('');
        }
    },

    QuickView: {
        open: (id) => {
            const i = App.State.catalog.find(x=>x.id===id); if(!i) return;
            App.Recent.add(id); // Hook for history
            const priceVal = App.Utils.getPriceObj(i).now;
            document.getElementById('quickview-content').innerHTML = `<div class="p-4 text-center"><img src="${i.img}" class="img-fluid rounded mb-3"/><h3>${i.title}</h3><h2 class="text-primary">${App.Utils.fmt(priceVal)}</h2><button class="btn btn-primary w-100 mt-3" onclick="App.Cart.add('${i.id}', null)">ADD TO CART</button></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        }
    },

    Wishlist: {
        checkClear: () => { if(App.State.wishlist.length===0) return; if(confirm('Empty Wishlist?')) App.Wishlist.clear(); },
        clear: () => { App.State.wishlist=[]; App.Utils.save('se_wish'); App.Wishlist.render(); document.getElementById('nav-wish-count').innerText=0; App.API.push('wishlist'); },
        toggle: (id, btn) => { 
            App.State.lastActive = Date.now();
            const idx = App.State.wishlist.findIndex(w => w.id === id);
            if(idx > -1) {
                App.State.wishlist.splice(idx, 1);
                if(btn) { btn.classList.remove('active'); btn.innerHTML = '<i class="bi bi-heart"></i>'; }
            } else {
                const item = App.State.catalog.find(i => i.id === id);
                if(item) {
                    App.State.wishlist.push(item);
                    if(btn) { btn.classList.add('active'); btn.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; }
                }
            }
            App.Utils.save('se_wish');
            document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
            if(window.location.hash === '#wishlist') App.Wishlist.render();
            App.API.push('wishlist'); 
        },
        render: () => { 
            const r = document.getElementById('wishlist-grid-root'); 
            if(!r) return;
            r.innerHTML=''; 
            if(App.State.wishlist.length === 0) {
                r.innerHTML = `<div class="col-12 text-center py-5"><i class="bi bi-heart text-muted display-4"></i><p class="mt-3 text-muted">No favorites yet.</p><button class="btn btn-primary rounded-pill" onclick="window.location.hash='#catalog'">Go to Menu</button></div>`;
                return;
            }
            App.State.wishlist.forEach(i => r.innerHTML += App.Catalog.createCard(i)); 
        }
    },

    Profile: {
        renderOrders: () => {
            const list = document.getElementById('order-history-list');
            if(!list) return;
            list.innerHTML = '';
            if(App.State.history.length === 0) {
                list.innerHTML = '<p class="text-muted text-center py-3">No orders yet.</p>';
                return;
            }
            App.State.history.forEach(o => {
                const date = new Date(o.date).toLocaleDateString();
                list.innerHTML += `<div class="card border-0 shadow-sm mb-3"><div class="card-body"><div class="d-flex justify-content-between"><span>${o.id}</span><small class="text-muted">${date}</small></div><div class="d-flex justify-content-between mt-2"><strong>${App.Utils.fmt(parseFloat(o.total))}</strong><span class="badge bg-light text-dark border">${o.status}</span></div></div></div>`;
            });
        }
    },

    i18n: {
        toggleLang: () => {
            const map = { 'EN': 'FR', 'FR': 'AR', 'AR': 'EN' };
            App.State.lang = map[App.State.lang];
            localStorage.setItem('se_lang', App.State.lang);
            App.i18n.apply();
            App.Catalog.renderFilters(); App.Catalog.renderBatch(true); App.Cart.render();
            if(window.location.hash === '#wishlist') App.Wishlist.render();
        },
        toggleCurrency: () => {
            App.State.lastCurrencyChange = Date.now(); 
            App.State.lastActive = Date.now();
            const map = { 'MAD': 'EUR', 'EUR': 'USD', 'USD': 'MAD' };
            App.State.currency = map[App.State.currency];
            localStorage.setItem('se_curr', App.State.currency);
            document.getElementById('curr-btn').innerText = App.State.currency;

            if(App.State.user) {
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'updatePreference', data: { userId: App.State.user.id, currency: App.State.currency } }) });
                App.API.push('cart'); 
            }
            App.Catalog.renderBatch(true); App.Cart.render();
            if(window.location.hash === '#wishlist') App.Wishlist.render();
        },
        apply: () => {
            // Simplified apply for now
        }
    },

    Router: (scroll=true) => {
        const h = window.location.hash || '#home';
        document.querySelectorAll('.module-section').forEach(e=>e.classList.remove('active'));
        const t = document.querySelector(h+'-module'); if(t) t.classList.add('active');
        document.getElementById('breadcrumbs').innerHTML = `<span class="fw-bold">🏠 ${h.replace('#','').toUpperCase()}</span>`;
        if(h==='#cart') document.getElementById('floating-cart').classList.remove('active');
        else App.Cart.render();
        if(h==='#profile') App.Auth.check();
        if(h==='#wishlist') App.Wishlist.render();
        if(scroll) window.scrollTo(0,0);
    }
};

document.addEventListener('DOMContentLoaded', () => {
    App.State.cart = App.Utils.load('se_cart');
    App.State.wishlist = App.Utils.load('se_wish');
    App.State.recent = App.Utils.load('se_recent');
    App.State.user = JSON.parse(localStorage.getItem('se_user'));
    App.State.lang = localStorage.getItem('se_lang') || 'EN';
    App.State.currency = localStorage.getItem('se_curr') || 'MAD';

    document.getElementById('curr-btn').innerText = App.State.currency;
    App.Auth.check();
    App.API.init(); 
    AOS.init();
    App.Cart.render(); 
    App.Cart.updateBadge();
    App.Router(); window.addEventListener('hashchange', App.Router);

    if(App.State.user) {
        App.API.syncDown(App.State.user.id);
        setInterval(() => {
           const isIdle = (Date.now() - App.State.lastActive) > 15000;
           if(App.State.user && isIdle) App.API.syncDown(App.State.user.id);
        }, 10000);
    }
});
//
